            flags |= _NEGATIVE
            line = line[1:]
        if line.endswith(b"/"):
            flags |= _MUSTBEDIR
            line = line[:-1]
        if b"/" not in line:
            flags |= _NODIR
        if line[:1] == b"*" and _simple_length(line[1:]) == len(line) - 1:
            flags |= _ENDSWITH
