            if last_space is None:
                last_space = i
        elif c == 0x5C:
            i += 1
            if i >= n:
                return s
            last_space = None
        else:
            last_space = None
        i += 1
    return s if last_space is None else s[:last_space]


def _parse_patterns(buf, base):
    if buf.startswith(b"\xef\xbb\xbf"):
        buf = buf[3:]
